export const CIRCUITS = [MUGELLO];

/** Track names differ between seeds ("Mugello Circuit" vs "Autodromo … del Mugello"), so match on a keyword. */
export function circuitFor(trackName) {
  const n = String(trackName || "").toLowerCase();
  return CIRCUITS.find((c) => c.match.some((m) => n.includes(m))) || null;
}
